head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[header > P > columnClass]<br/>GridView Header 의 각 Cell(th) 영역에 적용할 클래스의 이름을 설정합니다.",
    "validation" : [
        "CSS 파일이나 style 블럭에 정의된 클래스 이름을 설정합니다.",
        "하나의 클래스 이름을 설정할 수 있으며 공백으로 두 개 이상의 클래스를 설정할 수 없습니다.",
        "속성값은 Header Cell(th) 영역의 class 속성에 추가되는 것이 아니라 기존값을 치환합니다.",
        "속성값을 설정하지 않으면 기본 클래스인 'gridHeaderTDDefault' 가 설정됩니다.",
        "columnClass 속성값을 기준으로 파생 클래스 이름이 자동으로 생성됩니다.",
        "일반 Header Cell 에는 '{columnClass} {columnClass}_data {columnClass}_background' 등의 클래스가 설정됩니다.",
        "RowNum Column 의 Header Cell 에는 '{columnClass} {columnClass}_rowNumber {columnClass}_background' 등의 클래스가 설정됩니다.",
        "RowStatus Column 의 Header Cell 에는 '{columnClass} {columnClass}_rowStatus {columnClass}_background' 등의 클래스가 설정됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_columnClass.setValue("tcHeaderClass");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정
    //  - columnClass 는 dynamic N 이므로 렌더 시점에만 설정한다.
    let cColumnClass = con_columnClass.getValue();
    let lblColumnClass = (cColumnClass === '') ? '미설정' : cColumnClass;
    let attrColumnClass = (cColumnClass === '') ? '' : ' columnClass="' + cColumnClass + '"';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] GridView 하위 w2:header 에 columnClass 를 설정하고 rowNumVisible=true, rowStatusVisible=true 로 RowNum/RowStatus Column 을 표시 (Header 첫번째 Cell=RowNum, 두번째 Cell=RowStatus, 세번째 Cell부터 일반)\n[현재] header columnClass = ' + lblColumnClass + ' (샘플 style 블럭 정의 : tcHeaderClass = 연노랑 배경, tcHeaderClass_data = 굵은 글씨 + 빨강 테두리, tcHeaderClass_rowNumber = 파랑 배경, tcHeaderClass_rowStatus = 초록 배경, tcHeaderClass_background = 보라 이중 아래선, tcEtcClass = 기울임꼴 / 미설정 시 엔진 기본 테마)\n[절차] 옵션 변경 후 Target 재생성 -> 클래스 확인\n[확인] 세 종류 Header Cell(th) 의 실제 className 전문과 화면 표시를 결과창에서 확인"', '', 'label1');

    // dataList 생성 (col1~col4 / 4행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (header 에 columnClass 설정)
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" rowNumVisible="true" rowStatusVisible="true" id="" style="width:700px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1"' + attrColumnClass + '>';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 렌더된 Header Cell(th) 목록 조회 (첫번째 Row 기준 - 0:RowNum, 1:RowStatus, 2~:일반)
scwin.getHeaderCells = function () {
    let firstTh = target1.render.querySelector("th");
    if (!firstTh) {
        return [];
    }
    return Array.prototype.slice.call(firstTh.parentNode.querySelectorAll("th"));
}



// header 에 설정한 columnClass 의 실제 적용 여부 확인
scwin.btn_checkColumnClass_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");

    let cColumnClass = con_columnClass.getValue();
    let cells = scwin.getHeaderCells();
    let rowNumCell = cells[0];
    let rowStatusCell = cells[1];
    let dataCell = cells[2];

    let dataClassName = dataCell ? dataCell.className : '(없음)';
    let rowNumClassName = rowNumCell ? rowNumCell.className : '(없음)';
    let rowStatusClassName = rowStatusCell ? rowStatusCell.className : '(없음)';
    let cellStyle = dataCell ? window.getComputedStyle(dataCell) : null;
    let rowNumStyle = rowNumCell ? window.getComputedStyle(rowNumCell) : null;
    let rowStatusStyle = rowStatusCell ? window.getComputedStyle(rowStatusCell) : null;
    let dataTokens = dataClassName.split(/\s+/).filter(function (v) { return v !== ''; });
    let derived = [dataClassName, rowNumClassName, rowStatusClassName].join(' ').split(/\s+/).filter(function (v) { return /_(data|rowNumber|rowStatus|background)$/.test(v); });
    let baseToken = dataTokens.filter(function (v) { return /_data$/.test(v); }).join(', ').replace(/_data/g, '');
    let expectedBase = (cColumnClass === '') ? 'gridHeaderTDDefault' : cColumnClass;

    bottom.setReturnValue("[1] 설정한 columnClass : " + (cColumnClass === '' ? '(미설정)' : cColumnClass) + " / 일반 Header Cell 의 css 적용값(background-color, border) : " + (cellStyle ? cellStyle.backgroundColor + ", " + cellStyle.borderTopWidth + " " + cellStyle.borderTopStyle + " " + cellStyle.borderTopColor : '-'));
    bottom.setReturnValue("[2] 공백 포함 설정 여부 : " + (cColumnClass.indexOf(' ') > -1) + " / 일반 Header Cell 의 class 토큰 : " + dataTokens.join(' | '));
    bottom.setReturnValue("[3] 기본 클래스(gridHeaderTDDefault) 잔존 여부 : " + (dataTokens.indexOf('gridHeaderTDDefault') > -1));
    bottom.setReturnValue("[4] 미설정 여부 : " + (cColumnClass === '') + " / 렌더에 적용된 기준 클래스 : " + baseToken);
    bottom.setReturnValue("[5] 자동 생성된 파생 클래스 : " + derived.join(', '));
    bottom.setReturnValue("[6] 일반 Header Cell className : " + dataClassName);
    bottom.setReturnValue("[7] RowNum Header Cell className : " + rowNumClassName);
    bottom.setReturnValue("[8] RowStatus Header Cell className : " + rowStatusClassName);
    bottom.setReturnValue("[9] 파생 클래스가 설정값 전체(" + expectedBase + ")를 접두사로 갖는지 여부 : " + (derived.length > 0 && derived.every(function (v) { return v.indexOf(expectedBase + '_') === 0; })));
    bottom.setReturnValue("[10] 파생 클래스 CSS 적용값(RowNum background-color, RowStatus background-color, 일반 Cell border-bottom) : " + (rowNumStyle ? rowNumStyle.backgroundColor : '-') + ", " + (rowStatusStyle ? rowStatusStyle.backgroundColor : '-') + ", " + (cellStyle ? cellStyle.borderBottomWidth + " " + cellStyle.borderBottomStyle + " " + cellStyle.borderBottomColor : '-'));
}
